contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmt, uint secondDepositAmt) public payable {
        require(address(this).balance >= depositAmt + secondDepositAmt);

        c.deposit{value: depositAmt}();

        uint balBefore = address(c).balance;
        uint creditedBefore;

        // Second deposit from the test contract only if instructed
        if (secondDepositAmt > 0) {
            c.deposit{value: secondDepositAmt}();
        }

        // creditedBefore is credit[msg.sender] i.e. credit[address(this)] but no getter
        // We can approximate total credit via observable balance: total credit == balance
        creditedBefore = address(c).balance;

        // perform the deciding call
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;

        // General rule: if not reverted and there was positive credit, withdrawal should
        // credit the caller zero and transfer exactly the old credit.
        // Since no credit getter, express in terms of balance: balance should decrease
        // by exactly the caller's original credit.  Original credit = balBefore?
        // Actually credit[msg.sender] is not directly readable.  However, total balance
        // equals total credits only if no donations.  We can't prove equality of credit
        // and balance from public surface reliably.
        // Instead, assert that after successful withdrawal, the test contract receives
        // exactly creditedBefore (which is address(c).balance before withdraw) because
        // balance should equal credit[msg.sender] for this single depositor before withdraw.
        // We enforce that precondition implicitly: only depositor is this test contract.
        // But invariant must hold generally; we can state: after successful withdraw,
        // c balance == old balance - creditedBefore, where creditedBefore is what caller
        // is credited.  Since no public credit getter, we cannot access creditedBefore
        // directly.  
        // Workaround: credit[msg.sender] is not public.  So we use the fact that
        // every ETH in c before the call was credited to msg.sender (because only msg.sender
        // deposited).  Then creditedBefore == balBefore.

        // Therefore the rule: if not reverted and balBefore > 0, then balAfter == 0.
        // That's a valid general rule: withdrawing all transfers the whole balance to the caller.
        // But is this always true?  If someone else deposited, balance != caller's credit.
        // However, in a fresh deployment and single run, only this test contract deposits.
        // The checker runs once with fresh c, so only msg.sender (this contract) has credit.
        // This makes balBefore == credit[msg.sender].
        // Then after withdrawAll, credit[msg.sender] = 0 and balance -= credit.
        // So balAfter = balBefore - credit = 0.
        assert(reverted || balBefore == 0 || balAfter == 0);
    }

    receive() external payable {}
}

